#include <dshow.h>
#include <iostream>
const CLSID id={0x5b4131af,0x3298,0x47aa,{0x9c,0x12,0x33,0x40,0x7a,0x81,0x91,0x4b}};
#define CHECK(x) do {HRESULT h=(x);if(h!=S_OK){std::cerr<<#x<<" failed 0x"<<std::hex<<h<<"\n";return 1;}}while(0)
int main(){HMODULE m=LoadLibraryW(L"BandHeartBeatDirectShow.dll");if(!m)return 2;auto get=reinterpret_cast<HRESULT(WINAPI*)(REFCLSID,REFIID,void**)>(GetProcAddress(m,"DllGetClassObject"));if(!get)return 3;IClassFactory*c=nullptr;CHECK(get(id,IID_IClassFactory,(void**)&c));IBaseFilter*f=nullptr;CHECK(c->CreateInstance(nullptr,IID_IBaseFilter,(void**)&f));c->Release();IEnumPins*e=nullptr;CHECK(f->EnumPins(&e));IPin*p=nullptr;ULONG n=0;CHECK(e->Next(1,&p,&n));if(n!=1)return 4;IPin*found=nullptr;CHECK(f->FindPin(L"Output",&found));if(found!=p)return 5;found->Release();PIN_DIRECTION d;CHECK(p->QueryDirection(&d));if(d!=PINDIR_OUTPUT)return 6;PIN_INFO info{};CHECK(p->QueryPinInfo(&info));if(info.pFilter!=f)return 7;info.pFilter->Release();IEnumMediaTypes*types=nullptr;CHECK(p->EnumMediaTypes(&types));AM_MEDIA_TYPE*t=nullptr;CHECK(types->Next(1,&t,&n));if(t->subtype!=MEDIASUBTYPE_RGB32||t->formattype!=FORMAT_VideoInfo)return 8;auto v=reinterpret_cast<VIDEOINFOHEADER*>(t->pbFormat);if(v->bmiHeader.biWidth!=640||v->bmiHeader.biHeight!=480||v->AvgTimePerFrame!=2000000)return 9;std::cout<<"PASS class factory, IBaseFilter, EnumPins/FindPin identity, output IPin, RGB32 640x480 at 5fps\n";CoTaskMemFree(t->pbFormat);CoTaskMemFree(t);types->Release();CHECK(f->Run(0));FILTER_STATE s;CHECK(f->GetState(0,&s));if(s!=State_Running)return 10;CHECK(f->Pause());CHECK(f->Stop());p->Release();e->Release();f->Release();FreeLibrary(m);std::cout<<"PASS Run/Pause/Stop and COM release; no registration/camera access\n";return 0;}
